import {createIntegratedCalculator} from './calculator.js';

const link=(url,label)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} <span aria-hidden="true">↗</span></a>`;
const contact=(title,description,url,label='Sprawdź pomoc i kontakt')=>`<div class="support-contact"><h4>${title}</h4><p>${description}</p>${link(url,label)}</div>`;
const zus='https://www.zus.pl/swiadczenia/zasilki';
const supplement='https://www.zus.pl/-/zasi%C5%82ek-macierzy%C5%84ski-za-okres-uzupe%C5%82niaj%C4%85cego-urlopu-macierzy%C5%84skiego';

export function specialSupportHtml(){return `<div class="support-intro"><span class="eyebrow">Pomoc dopasowana do sytuacji</span><p>Wybierz temat. Znajdziesz tu pierwsze kroki, najważniejsze warunki i kontakty do osób, które mogą pomóc.</p><nav class="support-shortcuts" aria-label="Tematy wsparcia">${[['prematurity','Wcześniactwo'],['illness','Ciężka choroba'],['employment','Utrata pracy'],['loss','Po stracie'],['other','Inna sprawa']].map(([id,title])=>`<button type="button" data-support-jump="${id}">${title}</button>`).join('')}</nav></div>
<div class="support-topics">
 <article class="support-topic" id="support-prematurity"><div class="support-topic-title"><span class="support-topic-icon" aria-hidden="true">♡</span><div><span class="eyebrow">Po narodzinach</span><h3>Wcześniactwo i hospitalizacja dziecka</h3></div></div><div class="support-topic-columns"><div>
  <h4>Od czego zacząć?</h4><ol><li><strong>Oddział neonatologii lub lekarz prowadzący dziecko:</strong> poproś o plan dalszej opieki i zaświadczenie szpitala z datami pobytu, tygodniem ciąży przy porodzie oraz masą urodzeniową.</li><li><strong>Pracodawca:</strong> złóż wniosek o uzupełniający urlop macierzyński co najmniej 21 dni przed końcem macierzyńskiego. Dodatkowy urlop następuje bezpośrednio po nim, jednorazowo.</li><li><strong>ZUS lub płatnik zasiłku:</strong> ustal dokumenty do wypłaty. Osoba ubezpieczona, która nie jest pracownikiem, sprawdza prawo do zasiłku za odpowiadający okres — nie do urlopu pracowniczego.</li></ol>
  <h4>Kiedy można skorzystać?</h4><div class="support-rules"><p><strong>Do 15 tygodni</strong> — poród przed ukończeniem 28. tygodnia ciąży <strong>lub</strong> masa urodzeniowa do 1000 g włącznie; uwzględnia się hospitalizację w pierwszych 15 tygodniach po porodzie.</p><p><strong>Do 8 tygodni</strong> — poród od ukończonego 28. tygodnia do końca 36. tygodnia ciąży i masa powyżej 1000 g; uwzględnia się hospitalizację w pierwszych 8 tygodniach.</p><p><strong>Także po porodzie o czasie:</strong> przy co najmniej 2 kolejnych dniach hospitalizacji, z których pierwszy przypada między 5. a 28. dniem życia. Do wymiaru wlicza się właściwy pobyt od 5. dnia do końca 8. tygodnia po porodzie.</p></div>
  <p>Długość zależy od pobytu w szpitalu, a nie wyłącznie od wcześniactwa. Niepełny tydzień po zsumowaniu właściwych dni zaokrągla się w górę. Zasiłek za ten okres wynosi 100% podstawy wymiaru. Z dodatkowego urlopu może skorzystać uprawniona matka albo ojciec — nie są to dwa osobne urlopy dla obojga rodziców.</p>
  <details class="support-explanation"><summary>Co oznacza wcześniactwo i jak się je potwierdza?</summary><p><strong>Wcześniak to dziecko urodzone przed ukończeniem 37 tygodni ciąży</strong>, czyli najpóźniej przy wieku ciąży 36 tygodni i 6 dni. Od 37 tygodni i 0 dni poród nie jest już przedwczesny z tego powodu.</p><p>W medycznym podziale wyróżnia się wcześniactwo skrajne — przed 28 tygodniami, bardzo wczesne — od 28 do poniżej 32 tygodni oraz umiarkowane i późne — od 32 do poniżej 37 tygodni. To podział medyczny; progi urlopowe opisane wyżej są odrębne.</p><p>Wiek ciąży i stan dziecka ustala lekarz na podstawie dokumentacji medycznej. Dla urlopu i zasiłku znaczenie ma zaświadczenie szpitala z ukończonym tygodniem ciąży, masą i pobytami. Sama niska masa nie oznacza medycznie wcześniactwa, ale może spełniać osobny warunek dodatkowego urlopu.</p>${link('https://szczepienia.pzh.gov.pl/wszystko-o-szczepieniach/dlaczego-nalezy-szczepic-wczesniaki/?strona=2','Definicja wcześniaka — NIZP PZH')}${link('https://www.who.int/news-room/fact-sheets/detail/preterm-birth','Medyczny podział wcześniactwa — WHO')}</details>
  ${link(supplement,'Warunki i dokumenty — ZUS')}
 </div><aside class="support-contacts"><h4>Wsparcie dla Was</h4>${contact('Fundacja Wcześniak Rodzice–Rodzicom','Pomoc rodzicom wcześniaków: materiały, kontakt z doświadczonymi rodzicami i wypożyczalnia sprzętu. Sprawdź dostępność konkretnej formy pomocy.','https://wczesniak.pl/kontakt/')}${contact('Fundacja Ernesta — wcześniaki','Konsultacje dla rodzin wcześniaków. Na stronie znajdziesz zasady zgłoszenia i dostępne terminy.','https://fundacjaernesta.pl/regulamin-konsultacji-dla-wczesniakow/')}</aside></div></article>

 <article class="support-topic" id="support-illness"><div class="support-topic-title"><span class="support-topic-icon" aria-hidden="true">✚</span><div><span class="eyebrow">Zdrowie i opieka</span><h3>Ciężka choroba rodzica lub dziecka</h3></div></div><div class="support-topic-columns"><div><h4>Gdzie się zgłosić?</h4><ul><li><strong>Lekarz prowadzący lub rodzinny:</strong> ustal leczenie, potrzebę opieki i właściwy dokument medyczny.</li><li><strong>ZUS lub płatnik zasiłku:</strong> sprawdź chorobowe rodzica, opiekuńczy na dziecko lub bliskiego, a po wyczerpaniu chorobowego — rehabilitacyjne.</li><li><strong>Pracodawca i drugi rodzic:</strong> jeżeli matka nie może opiekować się noworodkiem, ustal właściwą ścieżkę dodatkowego opiekuńczego albo przejęcia części macierzyńskiego.</li><li><strong>Pracownik socjalny szpitala lub OPS/MOPS:</strong> zapytaj o pomoc w organizacji opieki i właściwy organ pozostałych świadczeń.</li></ul><details class="support-explanation"><summary>Choroba, niepełnosprawność i „Za życiem” — czym się różnią?</summary><p>Ciężka choroba sama nie zastępuje orzeczenia o niepełnosprawności ani zaświadczenia „Za życiem”. Do każdego uprawnienia potrzebny jest właściwy dokument.</p><p>Opiekuńczy zależy m.in. od powodu opieki, wieku, innych domowników i wspólnego wykorzystania limitu przez rodzinę. Rehabilitacyjne wymaga dalszej niezdolności, rokowania poprawy i rozstrzygnięcia ZUS. Zaświadczenie „Za życiem” może wpływać na wymiar rodzicielskiego, ale nie oznacza przyznania wszystkich świadczeń.</p>${link('https://www.zus.pl/swiadczenia/zasilki/zasilek-opiekunczy/prawo-do-zasilku-i-okres-przyslugiwania','Opiekuńczy — ZUS')}${link('https://www.zus.pl/swiadczenia/zasilki/swiadczenie-rehabilitacyjne','Rehabilitacyjne — ZUS')}</details></div><aside class="support-contacts"><h4>Pomoc przy konkretnej diagnozie</h4>${contact('Fundacja Gajusz — hospicjum perinatalne','Przy ciężkiej, nieuleczalnej chorobie rozpoznanej w ciąży: wsparcie medyczne, psychologiczne i organizacyjne w Łodzi. Placówka wskazuje wymagane skierowanie od lekarza ubezpieczenia zdrowotnego.','https://gajusz.org.pl/jak-pomagamy/hospicjum-perinatalne/pomoc/')}${contact('Alivia — choroba nowotworowa','Dla osoby z chorobą onkologiczną i jej bliskich: informacje, konsultacje i pomoc w odnalezieniu się w leczeniu. Zakres programów sprawdzisz w fundacji.','https://moja.alivia.org.pl/')}</aside></div></article>

 <article class="support-topic" id="support-employment"><div class="support-topic-title"><span class="support-topic-icon" aria-hidden="true">▤</span><div><span class="eyebrow">Praca i ubezpieczenie</span><h3>Utrata zatrudnienia w ciąży</h3></div></div><div class="support-topic-columns"><div><h4>Co zrobić najpierw?</h4><ol><li><strong>Zbierz dokumenty:</strong> umowę, pismo o jej zakończeniu, świadectwo pracy i zaświadczenie o ciąży. Zapisz daty i przyczynę zakończenia zatrudnienia.</li><li><strong>Skontaktuj się z ZUS:</strong> ustal chorobowe po ustaniu ubezpieczenia oraz ewentualne szczególne świadczenie przed porodem i macierzyńskie po porodzie.</li><li><strong>Sprawdź legalność zakończenia umowy:</strong> skorzystaj z pomocy PIP lub prawnika; przy sporze znaczenie ma także termin właściwej drogi sądowej.</li></ol><details class="support-explanation"><summary>Czy po końcu umowy zawsze tracę świadczenia?</summary><p>Nie. Znaczenie mają rodzaj umowy, jej daty, objęcie chorobowym i konkretna przyczyna ustania. Ochrona w ciąży nie przedłuża automatycznie każdej umowy.</p><p>Śmierć, upadłość lub likwidacja pracodawcy mogą uruchamiać szczególne uprawnienie do dnia porodu, jeśli nie zapewniono innego zatrudnienia. Naruszenie prawa potwierdzone prawomocnym orzeczeniem oraz przedłużenie umowy do porodu to inne podstawy. Zwykłe zakończenie zatrudnienia nie jest z nimi zamienne.</p>${link('https://www.zus.pl/swiadczenia/zasilki/zasilek-macierzynski/prawo-do-zasilku-i-okres-przyslugiwania/za-okres-urlopu-macierzynskiego-albo-urlopu-na-warunkach-urlopu-macierzynskiego','Szczególne uprawnienia po ustaniu pracy — ZUS')}</details></div><aside class="support-contacts"><h4>Właściwa pomoc prawna</h4>${contact('Państwowa Inspekcja Pracy','Sprawy ochrony zatrudnienia i praw pracowniczych. Przygotuj dokumenty umowy i jej rozwiązania.','https://www.pip.gov.pl/dla-pracodawcow/porady-prawne/rodzicielstwo','Prawa rodziców — PIP')}${contact('Nieodpłatna pomoc prawna','Punkt w Twoim powiecie pomoże ustalić dalsze kroki. Można sprawdzić zasady i umówić poradę, także zdalną.','https://www.gov.pl/web/nieodplatna-pomoc/np','Sprawdź zasady i zapisy')}</aside></div></article>

 <article class="support-topic" id="support-loss"><div class="support-topic-title"><span class="support-topic-icon" aria-hidden="true">♡</span><div><span class="eyebrow">Po stracie</span><h3>Urodzenie martwego dziecka lub śmierć dziecka</h3></div></div><div class="support-topic-columns"><div><h4>Pomoc i najbliższe formalności</h4><ul><li><strong>Szpital, lekarz lub położna:</strong> poproś o wyjaśnienie dokumentów medycznych, możliwości pożegnania i dostępnego wsparcia psychologicznego.</li><li><strong>Pracodawca oraz ZUS lub płatnik:</strong> zgłoś zdarzenie, aby ustalić właściwy okres macierzyńskiego lub zakończenie trwającego świadczenia. Ma znaczenie data zdarzenia i liczba pozostałych przy życiu dzieci.</li><li><strong>ZUS:</strong> jeśli poniesiono koszty pogrzebu, sprawdź odrębnie pogrzebowe — sam fakt straty nie oznacza jeszcze jego przyznania.</li></ul><details class="support-explanation"><summary>Jakie dokumenty i okresy mogą mieć znaczenie?</summary><p>Przy martwym urodzeniu lub śmierci przed upływem 8 tygodni życia macierzyński ma szczególne zasady minimalnego okresu; przy późniejszym zgonie obowiązują inne reguły. Trwający rodzicielski i ojcowski trzeba ocenić odrębnie.</p><p>W odpowiedniej procedurze po stracie ciąży przepisy dopuszczają zaświadczenie lekarza lub położnej bez ustalenia płci dziecka i bez aktu z adnotacją o martwym urodzeniu. Właściwy dokument zależy od sprawy — poproś szpital i płatnika o wskazanie potrzebnego zaświadczenia.</p>${link('https://www.gov.pl/web/rodzina/latwiejszy-dostep-do-swiadczen-po-stracie-ciazy','Dokumenty po stracie — Ministerstwo Rodziny')}</details><div class="support-funeral"><h4>Zasiłek pogrzebowy</h4><p>Potrzebne są informacje o dacie śmierci, podstawie prawa, osobie ponoszącej koszty i rachunkach. Nie musisz wcześniej wypełniać profilu ani danych o wieku dziecka.</p><button class="primary" id="special-funeral">Sprawdź zasiłek pogrzebowy <span aria-hidden="true">→</span></button>${link('https://www.zus.pl/pl/swiadczenia/zasilki/zasilek-pogrzebowy','Warunki, termin i Z-12 — ZUS')}</div></div><aside class="support-contacts"><h4>Nie zostajecie z tym sami</h4>${contact('Fundacja Ernesta','Bezpłatne wsparcie psychologiczne dla osób po poronieniu, martwym urodzeniu i w trudnej sytuacji okołoporodowej oraz ich bliskich.','https://fundacjaernesta.pl/wsparcie-psychologiczne/')}${contact('Fundacja Nagle Sami','Pomoc w żałobie po stracie bliskiej osoby, także dziecka. Na stronie znajdziesz aktualne formy kontaktu i zasady pomocy.','https://naglesami.org.pl/telefon-wsparcia-zaloba/')}${contact('Tumbo Pomaga — Fundacja Hospicyjna','Wsparcie i materiały dla dzieci oraz opiekunów po śmierci bliskiej osoby — także dla rodzeństwa.','https://tumbopomaga.pl/jak-pomagamy.html')}</aside></div></article>

 <article class="support-topic" id="support-other"><div class="support-topic-title"><span class="support-topic-icon" aria-hidden="true">…</span><div><span class="eyebrow">Indywidualna sprawa</span><h3>Inne szczególne okoliczności</h3></div></div><div class="support-topic-columns"><div><h4>Gdzie zacząć?</h4><p><strong>W ZUS</strong> przedstaw swoją sytuację: daty, tytuły ubezpieczenia, relację do dziecka, dotychczasowe świadczenia i posiadane decyzje. Możesz zapytać, jakich danych brakuje i kto jest właściwym płatnikiem.</p><p><strong>Przy problemie z organizacją opieki lub środkami utrzymania</strong> zgłoś się do OPS/MOPS, a w sprawach pieczy do PCPR. W sporze pracowniczym właściwe mogą być PIP i sąd pracy.</p><details class="support-explanation"><summary>Co przygotować do rozmowy?</summary><p>Ułóż krótką chronologię: co się wydarzyło i kiedy, jaką masz umowę lub ubezpieczenie, jakie okresy już wykorzystano i jakie pisma otrzymano. Oddziel datę zdarzenia od daty doręczenia decyzji.</p><p>Nie wysyłaj dokumentacji medycznej do przypadkowych podmiotów. Najpierw sprawdź, czy wybrana organizacja zajmuje się taką sytuacją i jak bezpiecznie przekazać potrzebne informacje.</p></details></div><aside class="support-contacts"><h4>Pomoc w ustaleniu kolejnych kroków</h4>${contact('ZUS — kontakt i e-wizyta','Zapytaj o swoją sprawę, dokumenty, terminy i sposób kontaktu z właściwą placówką.','https://www.zus.pl/o-zus/kontakt')}${contact('Nieodpłatne poradnictwo','Pomoc w rozeznaniu uprawnień i spraw urzędowych; zasady oraz zapisy publikuje Ministerstwo Sprawiedliwości.','https://www.gov.pl/web/nieodplatna-pomoc/np')}</aside></div></article>
</div>`;}

export function createSpecialSupport({sheet,sheetContent,getProfile,store,recordsStore,notify,openRecords}){
 let mode=null,scroll=0,entry=false;
 const marker='ppm-support-funeral';
 function open(){mode='support';sheetContent('Wsparcie w szczególnej sytuacji',specialSupportHtml());sheet.classList.add('support-sheet');sheet.querySelectorAll('[data-support-jump]').forEach(button=>button.onclick=()=>{const topic=sheet.querySelector('#support-'+button.dataset.supportJump),heading=topic.querySelector('h3');heading.tabIndex=-1;topic.scrollIntoView({behavior:'smooth',block:'start'});heading.focus({preventScroll:true});});sheet.querySelector('#special-funeral').onclick=()=>{scroll=sheet.scrollTop;openFuneral();};requestAnimationFrame(()=>{sheet.scrollTop=scroll;});}
 function back(){if(entry)history.back();else open();}
 function openFuneral(){
  mode='funeral';if(!entry){history.pushState({support:marker},'',location.href);entry=true;}
  sheetContent('Zasiłek pogrzebowy',`<button class="text-button support-back" id="support-return">← Wróć do wsparcia w szczególnej sytuacji</button><p class="support-funeral-intro">Sprawdź warunki na podstawie danych osoby zmarłej i osoby, która poniosła koszty pogrzebu.</p><div id="support-calculator"></div>`);
  sheet.classList.add('support-sheet');sheet.querySelector('#support-return').onclick=back;
  const context=getProfile()||{formal:true,caseStage:'loss',parentRole:'unspecified',children:[]};
  const flow=createIntegratedCalculator({getProfile:()=>context,store:{...store,draft:()=>{}},recordsStore,notify,sheetContent,onChange:()=>{},openCalendar:()=>notify('Zapisane terminy znajdziesz w kalendarzu po uzupełnieniu profilu.'),openRecords,embedded:true,onExit:back});
  flow.startFormalTopic('funeral');flow.mount(sheet.querySelector('#support-calculator'));
 }
 window.addEventListener('popstate',()=>{if(entry&&history.state?.support!==marker){entry=false;if(mode==='funeral'&&sheet.open)open();}});
 sheet.addEventListener('close',()=>{if(sheet.open)return;sheet.classList.remove('support-sheet');mode=null;scroll=0;if(entry){entry=false;history.back();}});
 return {open};
}
